package com.example.jobfinderapp.models;
public class CareerPreference { private int id,userId,categoryId; private String desiredPosition,careerLevel,jobType,expectedSalary,desiredLocation,workMode,yearsExperience,availableDate; public int getId(){return id;}public void setId(int v){id=v;}public int getUserId(){return userId;}public void setUserId(int v){userId=v;}public int getCategoryId(){return categoryId;}public void setCategoryId(int v){categoryId=v;}public String getDesiredPosition(){return desiredPosition;}public void setDesiredPosition(String v){desiredPosition=v;}public String getCareerLevel(){return careerLevel;}public void setCareerLevel(String v){careerLevel=v;}public String getJobType(){return jobType;}public void setJobType(String v){jobType=v;}public String getExpectedSalary(){return expectedSalary;}public void setExpectedSalary(String v){expectedSalary=v;}public String getDesiredLocation(){return desiredLocation;}public void setDesiredLocation(String v){desiredLocation=v;}public String getWorkMode(){return workMode;}public void setWorkMode(String v){workMode=v;}public String getYearsExperience(){return yearsExperience;}public void setYearsExperience(String v){yearsExperience=v;}public String getAvailableDate(){return availableDate;}public void setAvailableDate(String v){availableDate=v;} }
